for(const p of projects){const f=featured.includes(p.id),b=document.createElement('button');b.className=`node project-node ${f?'featured':'quiet'}`;b.dataset.project=p.id;b.setAttribute('aria-label',`${p.title}，查看预览`);b.innerHTML=`<span class="node-dot"></span>${f?`<span class="node-thumb"><img src="${p.cover}" alt=""></span>`:''}<span class="node-copy"><strong>${p.shortTitle.replace('&','&amp;')}</strong>${f?`<small>${p.en.replace('&','&amp;')}</small>`:''}</span>${f?'<span class="node-arrow">↗</span>':''}`;b.onclick=()=>{nodes.forEach(n=>n.el.classList.toggle('selected',n.id===p.id));onSelect(p.id);};labels.append(b);nodes.push({id:p.id,cat:p.cat,parent:`${p.cat}/${p.subcategory}`,project:p,pos:new THREE.Vector3(...projectPos[p.id]),el:b,kind:'project'});}
let connectionGeo=new THREE.BufferGeometry(),connections=new THREE.LineSegments(connectionGeo,new THREE.LineBasicMaterial({color:'#5187ae',transparent:true,opacity:.35,blending:THREE.AdditiveBlending}));root.add(connections);
