function resize(){width=canvas.clientWidth;height=canvas.clientHeight;mobile=width<761;baseZ=mobile?120:115;targetZ=baseZ;camera.position.z=baseZ;camera.aspect=width/height;camera.updateProjectionMatrix();renderer.setSize(width,height,false);nebula.uniforms.uAspect.value=width/height;root.position.y=mobile?-1:0;root.scale.setScalar(mobile?.96:1);nodes.forEach(n=>{n.pos.set(...(mobile?mobilePos[n.id]:(n.kind==='category'?categoryPos[n.id]:n.kind==='subcat'?subcategoryPos[n.id]:projectPos[n.id])));});links();onZoom(100);}
